files.content:
[hidden] { display: none !important; }

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2b2b3c;
  font-family: 'Courier New', Courier, monospace;
  font-size: 16px;
  color: #f0e6d2;
  padding: 16px;
}

.panel {
  background: #3e3e5c;
  border: 4px solid #f0e6d2;
  border-radius: 8px;
  padding: 24px;
  max-width: 800px;
  width: 100%;
  box-shadow: 0 0 0 4px #2b2b3c, 0 8px 0 0 #1a1a28;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #f0e6d2;
  text-shadow: 2px 2px 0 #1a1a28;
}

.timers {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

.timer {
  background: #2b2b3c;
  border: 3px solid #f0e6d2;
  border-radius: 6px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

h2 {
  font-size: 1.25rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #f0e6d2;
}

.display {
  font-size: 2.5rem;
  font-weight: bold;
  letter-spacing: 2px;
  color: #f0e6d2;
  background: #1a1a28;
  padding: 8px 16px;
  border-radius: 4px;
  border: 2px solid #f0e6d2;
  min-width: 160px;
  text-align: center;
}

.done {
  font-size: 1.25rem;
  font-weight: bold;
  color: #ff6b6b;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 0 0 8px #ff6b6b;
}

.controls {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 8px 20px;
  border: 3px solid #f0e6d2;
  border-radius: 4px;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: transform 0.05s, background 0.15s;
  background: #4a4a6a;
  color: #f0e6d2;
  box-shadow: 0 4px 0 #1a1a28;
}

button:hover {
  background: #5a5a7a;
}

button:focus-visible {
  outline: 3px solid #ffd93d;
  outline-offset: 2px;
}

button:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 #1a1a28;
}

button.start.active {
  background: #6b8e23;
}

button.start.active:hover {
  background: #7ba32e;
}

button.reset {
  background: #8b3a3a;
}

button.reset:hover {
  background: #a34444;
}

@media (min-width: 600px) {
  .timers {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 400px) {
  .display {
    font-size: 2rem;
    min-width: 120px;
  }
  .panel {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
}

const timers = {};

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
}

function initTimer(key, duration) {
  const display = document.getElementById('display-' + key);
  const done = document.getElementById('done-' + key);
  const startBtn = document.getElementById('start-' + key);
  const resetBtn = document.getElementById('reset-' + key);

  const state = {
    remaining: duration,
    duration: duration,
    interval: null,
    running: false,
    endTime: null
  };

  function updateDisplay() {
    display.textContent = formatTime(state.remaining);
  }

  function tick() {
    const now = Date.now();
    const diff = Math.max(0, Math.round((state.endTime - now) / 1000));
    state.remaining = diff;
    updateDisplay();
    if (state.remaining <= 0) {
      stopTimer();
      done.hidden = false;
      startBtn.textContent = 'Start';
      startBtn.classList.remove('active');
    }
  }

  function startTimer() {
    if (state.running) return;
    state.running = true;
    state.endTime = Date.now() + state.remaining * 1000;
    state.interval = setInterval(tick, 200);
    startBtn.textContent = 'Pause';
    startBtn.classList.add('active');
    done.hidden = true;
  }

  function stopTimer() {
    if (!state.running) return;
    state.running = false;
    clearInterval(state.interval);
    state.interval = null;
    startBtn.textContent = 'Start';
    startBtn.classList.remove('active');
  }

  function resetTimer() {
    stopTimer();
    state.remaining = state.duration;
    updateDisplay();
    done.hidden = true;
    startBtn.textContent = 'Start';
    startBtn.classList.remove('active');
  }

  startBtn.addEventListener('click', function () {
    if (state.running) {
      stopTimer();
    } else {
      if (state.remaining <= 0) {
        state.remaining = state.duration;
        updateDisplay();
        done.hidden = true;
      }
      startTimer();
    }
  });

  resetBtn.addEventListener('click', resetTimer);

  updateDisplay();
  timers[key] = state;
}

initTimer('eggs', 360);
initTimer('pasta', 540);
initTimer('tea', 180);
